import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0015: 为什么核心维护内部集成工具箱，插件只是规则层","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0015-internal-toolbox-plugin-rule-layer.md","filePath":"zh/adr/ADR-0015-internal-toolbox-plugin-rule-layer.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0015-internal-toolbox-plugin-rule-layer.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0015-为什么核心维护内部集成工具箱-插件只是规则层" tabindex="-1">ADR-0015: 为什么核心维护内部集成工具箱，插件只是规则层 <a class="header-anchor" href="#adr-0015-为什么核心维护内部集成工具箱-插件只是规则层" aria-label="Permalink to “ADR-0015: 为什么核心维护内部集成工具箱，插件只是规则层”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：adr-principles.md §17.15，ADR-0002，ADR-0012</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>探测与恢复动作覆盖 HTTP、RPC、SSH、服务控制等传输/协议。若每个插件各自实现 传输，安全硬化（TLS 校验、SSRF 防护、SSH 主机密钥验证、超时/重试/取消、 凭据安全读取）会被 N 份实现稀释，无法统一强制。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>核心收敛一组&quot;内部集成工具&quot;作为能力执行器（HTTP 客户端、RPC 客户端、SSH 客户端、 进程/服务/磁盘/网络连通性探测、受控命令执行、重启控制），以 Capability + OperationParams 对外声明。插件与内置能力走同一张派发表：内置能力由核心进程内 执行器执行，插件声明的能力由插件子进程执行。插件不再自实现底层传输，只提供 能力声明与规则逻辑（目标、参数、决策、验证）。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>插件自包含、各自实现传输</strong>：重复实现；安全硬化易被绕过（某个插件关掉 TLS 校验即可）；插件体积与攻击面大。</li><li><strong>只允许内置能力（无插件）</strong>：场景化逻辑（mihomo/OpenClash 的领域决策） 无法由社区贡献。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：传输安全集中硬化一次（webhook 的 SSRF 防护就是第一个实例）； 超时/取消/预算/审计语义统一；插件变薄、可审计。 缺点：核心的工具面需要持续维护；插件自由度下降（不能任意实现自定义协议）—— 有新协议需求时先在核心加工具，再在插件层写规则。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>P2 平台适配器（systemd/launchd/SCM、网络接口/路由/DNS）作为工具执行器注册进 同一注册表。</li><li>Webhook 通知渠道复用工具箱的 HTTP 客户端语义（含 SSRF 策略，已实现）。</li><li>Python 出向绑定（todo P1）暴露的是工具调用，不是任意代码执行。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};